            const model = str(p.model) ?? str(getHarness(platformOf(name))?.models?.[alias]);
            if (model === undefined)
                continue;
            mergedHarnesses[name] ??= {};
            modelsOf(mergedHarnesses[name])[alias] = model;
            folded = true;
